package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/Shopify/sarama"
)

var encryptionKey = []byte("0123456789abcdef0123456789abcdef")

type EncryptedMessage struct {
	Ciphertext string `json:"ciphertext"`
	IV         string `json:"iv"`
}

func pkcs7Unpad(data []byte) ([]byte, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}
	padLen := int(data[len(data)-1])
	if padLen == 0 || padLen > aes.BlockSize {
		return nil, fmt.Errorf("invalid padding length: %d", padLen)
	}
	for i := len(data) - padLen; i < len(data); i++ {
		if data[i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding byte at position %d", i)
		}
	}
	return data[:len(data)-padLen], nil
}

func decryptPayload(msg EncryptedMessage) ([]byte, error) {
	ciphertextBytes, err := hex.DecodeString(msg.Ciphertext)
	if err != nil {
		return nil, fmt.Errorf("hex decode error")
	}
	ivBytes, err := hex.DecodeString(msg.IV)
	if err != nil {
		return nil, fmt.Errorf("iv decode error")
	}
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}
	mode := cipher.NewCBCDecrypter(block, ivBytes)
	plaintext := make([]byte, len(ciphertextBytes))
	mode.CryptBlocks(plaintext, ciphertextBytes)
	return pkcs7Unpad(plaintext)
}

// Health/debug endpoint that also accepts manual message submission
func handleDecrypt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var msg EncryptedMessage
	if err := json.NewDecoder(r.Body).Decode(&msg); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	_, err := decryptPayload(msg)
	if err != nil {
		if strings.Contains(err.Error(), "invalid padding") {
			http.Error(w, "decryption failed: padding error", http.StatusBadRequest)
		} else {
			http.Error(w, "decryption failed: processing error", http.StatusInternalServerError)
		}
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("message processed successfully"))
}

func consumeMessages(brokers []string, topic string) {
	config := sarama.NewConfig()
	config.Consumer.Return.Errors = true
	consumer, err := sarama.NewConsumer(brokers, config)
	if err != nil {
		log.Fatalf("Failed to create consumer: %v", err)
	}
	defer consumer.Close()

	partitionConsumer, err := consumer.ConsumePartition(topic, 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatalf("Failed to consume partition: %v", err)
	}
	defer partitionConsumer.Close()

	for msg := range partitionConsumer.Messages() {
		var encMsg EncryptedMessage
		if err := json.Unmarshal(msg.Value, &encMsg); err != nil {
			log.Printf("Failed to unmarshal message: %v", err)
			continue
		}
		plaintext, err := decryptPayload(encMsg)
		if err != nil {
			log.Printf("Decryption failed for offset %d: %v", msg.Offset, err)
			continue
		}
		log.Printf("Processed message: %s", string(plaintext))
	}
}

func main() {
	brokers := []string{"kafka-broker-1:9092", "kafka-broker-2:9092"}
	topic := "encrypted-events"

	go consumeMessages(brokers, topic)

	// Debug/admin HTTP interface on port 8080
	http.HandleFunc("/api/v1/decrypt", handleDecrypt)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	log.Println("Starting admin interface on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
